// Extract deals array from HubSpot search response
const response = $input.first().json;
const deals = response.results || [];
return deals.map(deal => ({
  json: {
    deal_id: deal.id,
    ...deal.properties
  }
}));

// ═══════════════════════════════════════════
// KINGA — Rep Snapshot Compute
// ═══════════════════════════════════════════
const REP_ID = 'kinga';
const deals = $input.all().map(i => i.json);
const invoiceResp = $('QuickBooks — Fetch Invoices YTD').first().json;
const invoices = invoiceResp.QueryResponse?.Invoice || [];
const custMap = $('Postgres — Fetch Customer Map').all().map(i => i.json);

// Filter invoices to this rep's customers
const repCustIds = new Set(
  custMap.filter(m => m.rep_id === REP_ID).map(m => m.qbo_customer_id)
);
const repInvoices = invoices.filter(inv =>
  repCustIds.has(String(inv.CustomerRef?.value))
);

const now = new Date();
const yearStart = new Date(now.getFullYear(), 0, 1);
const qtrMonth = Math.floor(now.getMonth() / 3) * 3;
const qtrStart = new Date(now.getFullYear(), qtrMonth, 1);
const monStart = new Date(now.getFullYear(), now.getMonth(), 1);
// Week start = Monday
const dayOfWeek = now.getDay() || 7;
const wkStart = new Date(now);
wkStart.setDate(now.getDate() - dayOfWeek + 1);
wkStart.setHours(0,0,0,0);

function productRevenue(inv) {
  return (inv.Line || [])
    .filter(l => l.DetailType === 'SalesItemLineDetail')
    .filter(l => {
      const ref = l.SalesItemLineDetail?.ItemAccountRef?.name || '';
      return ref.includes('41000') || ref.includes('43000') ||
             ref.includes('44000') || ref.includes('45000');
    })
    .reduce((sum, l) => sum + parseFloat(l.Amount || 0), 0);
}

function inPeriod(inv, start) {
  return new Date(inv.TxnDate) >= start;
}

const rev_wtd = repInvoices.filter(i => inPeriod(i, wkStart)).reduce((s,i) => s + productRevenue(i), 0);
const rev_mtd = repInvoices.filter(i => inPeriod(i, monStart)).reduce((s,i) => s + productRevenue(i), 0);
const rev_qtd = repInvoices.filter(i => inPeriod(i, qtrStart)).reduce((s,i) => s + productRevenue(i), 0);
const rev_ytd = repInvoices.filter(i => inPeriod(i, yearStart)).reduce((s,i) => s + productRevenue(i), 0);

const closedDeals = deals.filter(d => d.hs_is_closed_won === 'true');
const deals_mtd = closedDeals.filter(d => new Date(d.closedate) >= monStart).length;
const deals_ytd = closedDeals.filter(d => new Date(d.closedate) >= yearStart).length;

const ytdInvoices = repInvoices.filter(i => inPeriod(i, yearStart));
const avg_order = ytdInvoices.length > 0 ? rev_ytd / ytdInvoices.length : 0;

// Sales velocity: avg days from deal create to close
const velocities = closedDeals
  .filter(d => d.createdate && d.closedate)
  .map(d => (new Date(d.closedate) - new Date(d.createdate)) / 86400000);
const velocity = velocities.length > 0
  ? velocities.reduce((a,b) => a+b, 0) / velocities.length : 0;

const today = now.toISOString().slice(0, 10);

return [{
  json: {
    rep_id: REP_ID,
    snapshot_date: today,
    revenue_wtd: Math.round(rev_wtd * 100) / 100,
    revenue_mtd: Math.round(rev_mtd * 100) / 100,
    revenue_qtd: Math.round(rev_qtd * 100) / 100,
    revenue_ytd: Math.round(rev_ytd * 100) / 100,
    deals_closed_mtd: deals_mtd,
    deals_closed_ytd: deals_ytd,
    avg_order_size: Math.round(avg_order * 100) / 100,
    sales_velocity_days: Math.round(velocity * 10) / 10
  }
}];

// ═══════════════════════════════════════════
// KINGA — Pipeline Deal Age
// ═══════════════════════════════════════════
const STAGE_NAMES = {
  '4546923': 'Opportunities',
  '4546927': 'Quote Sent',
  '1337550105': 'Stale/Expired Quote',
  '4546928': 'Closed Won (Invoice Sent)',
  'closedlost': 'Closed Lost',
  '943265375': 'Hold',
  'interested_bad_timing': 'Interested but bad timing'
};

const deals = $input.all().map(i => i.json);
const today = new Date().toISOString().slice(0, 10);
const now = new Date();

const openDeals = deals.filter(d =>
  d.hs_is_closed_won !== 'true' && d.dealstage !== 'closedlost'
);

return openDeals.map(d => {
  const created = new Date(d.createdate);
  const daysInStage = d.hs_lastmodifieddate
    ? Math.floor((now - new Date(d.hs_lastmodifieddate)) / 86400000)
    : Math.floor((now - created) / 86400000);

  return {
    json: {
      rep_id: 'kinga',
      deal_id: d.deal_id || d.hs_object_id,
      deal_name: d.dealname,
      stage: STAGE_NAMES[d.dealstage] || d.dealstage,
      value: parseFloat(d.amount || 0),
      days_in_stage: daysInStage,
      last_stage_change: d.hs_lastmodifieddate || d.createdate,
      snapshot_date: today
    }
  };
});

