const repCustIds = new Set(repCusts.map(m => m.qbo_customer_id));
const custVertical = Object.fromEntries(
  repCusts.map(m => [m.qbo_customer_id, m.vertical])
);
const custName = Object.fromEntries(
  repCusts.map(m => [m.qbo_customer_id, m.qbo_customer_name])
);

const now = new Date();
