// KINGA — Sport Level Snapshots
// ═══════════════════════════════════════════
// Sport levels: Pro, D1, D2/D3, HS
// Mapping from customer name patterns to level.
// TODO: Move this mapping to a DB table for maintainability.
const SPORT_LEVELS = {
  // Pro teams / orgs
  'MLB': 'Pro', 'MLS': 'Pro', 'NFL': 'Pro', 'NWSL': 'Pro',
  'ATP Tour': 'Pro', 'Nutrabolt': 'Pro',
  'Human Powered Health': 'Pro', 'Freestyle Nutrition': 'Pro',
  // D1 university keywords
  'University': 'D1', 'State': 'D1', 'College': 'D1',
  // Academy / youth
  'Academy': 'HS', 'Sports Academy': 'HS',
};

function classifyLevel(name) {
  if (!name) return 'Unknown';
  const upper = name.toUpperCase();
  for (const [keyword, level] of Object.entries(SPORT_LEVELS)) {
    if (upper.includes(keyword.toUpperCase())) return level;
  }
  return 'D1'; // Default for Kinga's athletics customers
}

